PRAGMA foreign_keys = ON;
CREATE TABLE ProductCategory (CategoryID INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE CHECK(length(trim(Name))>0));
CREATE TABLE Position (PositionID INTEGER PRIMARY KEY, Name TEXT NOT NULL CHECK(length(trim(Name))>0), Salary REAL NOT NULL CHECK(Salary>=0));
CREATE TABLE Supplier (SupplierID INTEGER PRIMARY KEY, Name TEXT NOT NULL CHECK(length(trim(Name))>0), Email TEXT);
CREATE TABLE Product (ProductID INTEGER PRIMARY KEY, CategoryID INTEGER NOT NULL REFERENCES ProductCategory(CategoryID) ON UPDATE RESTRICT ON DELETE RESTRICT, Name TEXT NOT NULL CHECK(length(trim(Name))>0), Price REAL NOT NULL CHECK(Price>=0));
CREATE TABLE Employee (EmployeeID INTEGER PRIMARY KEY, PositionID INTEGER NOT NULL REFERENCES Position(PositionID) ON UPDATE RESTRICT ON DELETE RESTRICT, Surname TEXT NOT NULL, Name TEXT NOT NULL, Patronymic TEXT, INN TEXT, Phone TEXT, HireDate TEXT NOT NULL, DismissalDate TEXT, CHECK(DismissalDate IS NULL OR DismissalDate>=HireDate));
CREATE TABLE Supply (SupplyID INTEGER PRIMARY KEY, SupplierID INTEGER NOT NULL REFERENCES Supplier(SupplierID) ON UPDATE RESTRICT ON DELETE RESTRICT, SupplyDate TEXT NOT NULL);
CREATE TABLE SupplyProduct (RecordID INTEGER PRIMARY KEY, SupplyID INTEGER NOT NULL REFERENCES Supply(SupplyID) ON UPDATE RESTRICT ON DELETE RESTRICT, ProductID INTEGER NOT NULL REFERENCES Product(ProductID) ON UPDATE RESTRICT ON DELETE RESTRICT, Quantity REAL NOT NULL CHECK(Quantity>0), ExpirationDate TEXT, SupplierPrice REAL NOT NULL CHECK(SupplierPrice>=0), UNIQUE(SupplyID,ProductID));
CREATE TABLE Sale (SaleID INTEGER PRIMARY KEY, EmployeeID INTEGER NOT NULL REFERENCES Employee(EmployeeID) ON UPDATE RESTRICT ON DELETE RESTRICT, SaleDate TEXT NOT NULL, PaymentMethod TEXT NOT NULL, MaskedCard TEXT);
CREATE TABLE SaleProduct (RecordID INTEGER PRIMARY KEY, SaleID INTEGER NOT NULL REFERENCES Sale(SaleID) ON UPDATE RESTRICT ON DELETE RESTRICT, ProductID INTEGER NOT NULL REFERENCES Product(ProductID) ON UPDATE RESTRICT ON DELETE RESTRICT, Quantity REAL NOT NULL CHECK(Quantity>0), Sum REAL NOT NULL CHECK(Sum>=0), UNIQUE(SaleID,ProductID));
CREATE TABLE "Return" (ReturnID INTEGER PRIMARY KEY, SaleID INTEGER NOT NULL REFERENCES Sale(SaleID) ON UPDATE RESTRICT ON DELETE RESTRICT, EmployeeID INTEGER NOT NULL REFERENCES Employee(EmployeeID) ON UPDATE RESTRICT ON DELETE RESTRICT);
CREATE TABLE ReturnProduct (RecordID INTEGER PRIMARY KEY, ReturnID INTEGER NOT NULL REFERENCES "Return"(ReturnID) ON UPDATE RESTRICT ON DELETE RESTRICT, ProductID INTEGER NOT NULL REFERENCES Product(ProductID) ON UPDATE RESTRICT ON DELETE RESTRICT, Quantity REAL NOT NULL CHECK(Quantity>0), Sum REAL NOT NULL CHECK(Sum>=0), UNIQUE(ReturnID,ProductID));
CREATE TABLE WriteOff (WriteOffID INTEGER PRIMARY KEY, EmployeeID INTEGER NOT NULL REFERENCES Employee(EmployeeID) ON UPDATE RESTRICT ON DELETE RESTRICT, Reason TEXT NOT NULL, WriteOffDate TEXT NOT NULL);
CREATE TABLE WriteOffProduct (RecordID INTEGER PRIMARY KEY, WriteOffID INTEGER NOT NULL REFERENCES WriteOff(WriteOffID) ON UPDATE RESTRICT ON DELETE RESTRICT, ProductID INTEGER NOT NULL REFERENCES Product(ProductID) ON UPDATE RESTRICT ON DELETE RESTRICT, Quantity REAL NOT NULL CHECK(Quantity>0), UNIQUE(WriteOffID,ProductID));
CREATE INDEX IX_SupplyProduct_Product ON SupplyProduct(ProductID);
CREATE INDEX IX_SaleProduct_Product ON SaleProduct(ProductID);
CREATE INDEX IX_ReturnProduct_Product ON ReturnProduct(ProductID);
CREATE INDEX IX_WriteOffProduct_Product ON WriteOffProduct(ProductID);
CREATE VIEW Stock AS SELECT p.ProductID,p.Name,c.Name AS Category,p.Price,
 COALESCE((SELECT SUM(Quantity) FROM SupplyProduct WHERE ProductID=p.ProductID),0)
 +COALESCE((SELECT SUM(Quantity) FROM ReturnProduct WHERE ProductID=p.ProductID),0)
 -COALESCE((SELECT SUM(Quantity) FROM SaleProduct WHERE ProductID=p.ProductID),0)
 -COALESCE((SELECT SUM(Quantity) FROM WriteOffProduct WHERE ProductID=p.ProductID),0) AS Quantity
 FROM Product p JOIN ProductCategory c ON c.CategoryID=p.CategoryID;
